// Flattens a Jotform submission into one flat row: { "Question label": "answer" }.
// Works for any form layout: nested answers (name, address, date, etc.) become
// readable strings and lists are joined with commas.
function flatten(v) {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.map(flatten).filter(s => s !== '').join(', ');
  if (typeof v === 'object') {
    // Date/time widgets: { month, day, year } -> YYYY-MM-DD
    if ('year' in v && 'month' in v && 'day' in v) {
      return `${v.year}-${String(v.month).padStart(2, '0')}-${String(v.day).padStart(2, '0')}`;
    }
    return Object.values(v).map(flatten).filter(s => s !== '').join(' ');
  }
  return String(v).trim();
}

return $input.all().map(item => {
  const row = {
    'Submitted At': new Date().toISOString(),
    'Form ID': '262953147045055',
  };
  for (const [label, value] of Object.entries(item.json)) {
    row[label] = flatten(value);
  }
  return { json: row };
});

// Builds the notification e-mail and finds the submitter's e-mail address
// (the first answer whose label mentions "email" and contains an @).
const esc = s => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return $input.all().map(item => {
  const row = item.json;
  let submitterEmail = '';
  let submitterName = '';
  const rows = [];

  for (const [label, value] of Object.entries(row)) {
    if (!submitterEmail && /e-?mail/i.test(label) && /\S+@\S+\.\S+/.test(value)) {
      submitterEmail = value.match(/\S+@\S+\.\S+/)[0];
    }
    if (!submitterName && /name/i.test(label) && value) submitterName = value;
    rows.push(
      `<tr><td style="padding:6px 10px;border:1px solid #ddd;background:#f6f6f6;font-weight:600">${esc(label)}</td>` +
      `<td style="padding:6px 10px;border:1px solid #ddd">${esc(value || '—')}</td></tr>`
    );
  }

  return {
    json: {
      submitterEmail,
      submitterName,
      subject: `New form submission${submitterName ? ' from ' + submitterName : ''}`,
      html: `<p>A new response was submitted to Jotform form ${esc(row['Form ID'])}.</p>` +
            `<table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px">${rows.join('')}</table>`,
    },
  };
});
